window.AUTH=window.AUTH||{};window.AUTH["23-975"]={"d":"23-975","id":"2024/23-975","n":"Seven County Infrastructure Coalition v. Eagle County, Colorado","briefs":[{"k":"petitioner","label":"Brief of petitioners Seven County Infrastructure Coalition, et al.","date":"2024-08-28","url":"https://www.supremecourt.gov/DocketPDF/23/23-975/323596/20240828134634422_23-975%20Brief%20for%20Petitioners.pdf","side":"pet","n":39},{"k":"respondent","label":"Brief of federal respondents in support of petitioners","date":"2024-08-28","url":"https://www.supremecourt.gov/DocketPDF/23/23-975/323639/20240828215222594_23-975tsUnitedStates.pdf","side":"res","n":48},{"k":"respondent","label":"Brief of respondent Eagle County, Colorado","date":"2024-10-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-975/328667/20241018150415181_10.18.2024_7County%20Response%20Brief_Final.pdf","side":"res","n":74},{"k":"respondent","label":"Brief of respondents Center for Biological Diversity, et al.","date":"2024-10-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-975/328676/20241018152919651_No.%2023-975%20Envtl%20Rs%20Brief.pdf","side":"res","n":120},{"k":"reply","label":"Reply of petitioners Seven County Infrastructure Coalition, et al.","date":"2024-11-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-975/332070/20241118133305864_2024-11-18%207C%20merits%20reply%20FINAL.pdf","side":"pet","n":23}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us1r34_h3ci.pdf","tr":true,"items":[{"t":"case","label":"Aberdeen & Rockfish R.R. Co. v. SCRAP","cite":"422 U.S. 289","y":1975,"id":"1974/73-1966","sc":1,"op":2,"sum":"In December 1971, the Nation's railroads, citing sharply increasing costs and decreasing or negative profits, collectively proposed to file tariffs increasing their freight rates by a temporary surcharge across the board. The Interstate Commerce Commission (ICC), in the ensuing general revenue proceeding, finding that the railroads had a critical and immediate need for revenue, declined to exercise its power to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","4":"5"}},{"t":"case","label":"Baltimore Gas & Elec. Co. v. Nat. Res. Def. Council","cite":"462 U.S. 87","y":1983,"id":"1982/82-524","sc":1,"op":2,"sum":"The NRC complied with NEPA, and its decision is not arbitrary or capricious within the meaning of § 10(e) of the Administrative Procedure Act (APA).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 25, 43","2":"4"}},{"t":"case","label":"CSX Transp., Inc. v. McBride","cite":"564 U.S. 685","y":2011,"id":"2010/10-235","sc":1,"sum":"The Supreme Court affirmed the lower court order in an opinion by Justice Ruth Bader Ginsburg. \"The charge proper in FELA cases, we hold, simply tracks the language Congress employed, informing juries that a defendant railroad caused or contributed to a plaintiff employee's injury if the railroad's negligence played any part in bringing about the injury,\" Ginsburg wrote for the majority.","sumSrc":"Oyez","by":{"0":"27","1":"23, 36","2":"33","3":"38","4":"6"}},{"t":"case","label":"Ctr. for Biological Diversity v. Bernhardt","cite":"982 F.3d 723","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/982/723/","by":{"0":"5"}},{"t":"case","label":"Ctr. for Biological Diversity v. U.S. Army Corps of Eng’rs","cite":"941 F.3d 1288","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/941/1288/","by":{"0":"6","2":"27","4":"10"}},{"t":"case","label":"Dep’t of Transp. v. Public Citizen","cite":"541 U.S. 752","y":2004,"id":"2003/03-358","sc":1,"op":18,"sum":"The Court held that the FMCSA had no control of the trucks once the regulations were passed, and would therefore be unable to act on the findings of an EIS even if it did conduct one. Further, the Court found that the passage of the regulations was not sufficiently responsible for the increased pollution caused by the trucks to warrant an EIS.","sumSrc":"Oyez","by":{"0":"2, 5, 16, 17, 18, 22, 23, 26, 32, 35, 44","1":"2, 9, 14, 17, 18, 20-28, 31, 33-36, 45","2":"4, 29, 31, 32, 36","3":"14, 21, 23, 24, 29, 33, 35, 36, 37","4":"1, 5, 6, 10, 11, 17"}},{"t":"case","label":"Holmes v. Sec. Inv’r Prot. Corp.","cite":"503 U.S. 258","y":1992,"id":"1991/90-727","sc":1,"sum":"SIPC has demonstrated no right to sue Holmes under § 1964(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","4":"8"}},{"t":"case","label":"Kentuckians for the Commonwealth v. U.S. Army Corps of Eng’rs","cite":"746 F.3d 698","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/746/698/","by":{"0":"6"}},{"t":"case","label":"Kisor v. Wilkie","cite":"588 U.S. 558","y":2019,"id":"2018/18-15","sc":1,"op":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45"}},{"t":"case","label":"Kleppe v. Sierra Club","cite":"427 U.S. 390","y":1976,"id":"1975/75-552","sc":1,"op":5,"sum":"Section 102 (2) (C) of the National Environmental Policy Act of 1969 (NEPA) requires that all federal agencies include an environmental impact statement (EIS) \"in every recommendation or report on proposals for legislation and other major Federal actions significantly affecting the quality of the human environment.\" Respondent environmental organizations, alleging a widespread interest in the rich coal reserves of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","1":"28, 29"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"20","1":"36"}},{"t":"case","label":"Marsh v. Or. Nat. Res. Council","cite":"490 U.S. 360","y":1989,"id":"1988/87-1704","sc":1,"op":8,"sum":"The Elk Creek Dam is part of a three-dam project designed to control the water supply in Oregon's Rogue River Basin. The Army Corps of Engineers (Corps) completed an Environmental Impact Statement (EIS) for the Elk Creek project in 1971, and, in 1980, released its final Environmental Impact Statement, Supplement No. 1 (FEISS). Since the Rogue River is a premier fishing ground, the FEISS paid special heed to water …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 44","1":"20, 28","3":"25, 36, 45","4":"17, 18"}},{"t":"case","label":"Metro. Edison Co. v. People Against Nuclear Energy","cite":"460 U.S. 766","y":1983,"id":"1982/81-2399","sc":1,"op":11,"ar":1,"sum":"The NRC need not consider PANE's contentions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 5, 16, 17, 18, 19, 20, 21, 30, 32, 33, 35, 36, 38, 40, 41, 42, 43, 45, 49","1":"22, 23, 35","2":"3, 29, 30, 31, 34, 47, 49","3":"20, 29, 34, 43","4":"1, 5, 6, 7"}},{"t":"case","label":"Mid-States Coal. for Progress v. STB","cite":"345 F.3d 520","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/345/520/","by":{"0":"13"}},{"t":"case","label":"N.J. Dep’t of Env’t Prot. v. U.S. Nuclear Reg. Comm’n","cite":"561 F.3d 132","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/561/132/","by":{"0":"6"}},{"t":"case","label":"N.Y. Nat. Res. Def. Council, Inc. v. Kleppe","cite":"97 S. Ct. 4","y":1976,"url":"https://www.courtlistener.com/c/S.%20Ct./97/4/","sc":1,"by":{"0":"18","4":"19"}},{"t":"case","label":"Ohio Valley Coal. v. Aracoma Coal Co.","cite":"556 F.3d 177","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/556/177/","by":{"0":"6"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"0":"28","3":"40"}},{"t":"case","label":"Protect Our Parks v. Buttigieg","cite":"39 F.4th 389","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/39/389/","by":{"0":"6"}},{"t":"case","label":"Robertson v. Methow Valley City Council","cite":"490 U.S. 332","y":1989,"id":"1988/87-1703","sc":1,"op":8,"ar":1,"sum":"The Forest Service is authorized by statute to manage national forests for, inter alia, recreational purposes. Because its decision to issue a recreational special use permit is a \"major Federal action\" within the meaning of the National Environmental Policy Act of 1969 (NEPA), that decision must be preceded by the preparation of an Environmental Impact Statement (EIS). After a Service study designated a particular …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 4, 24, 38, 45","1":"2, 16, 20","2":"4, 25, 34, 39, 40","3":"4, 5, 24, 25, 36, 41","4":"4"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Sierra Club v. FERC","cite":"867 F.3d 1357","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1357/","op":1,"by":{"0":"5, 48","2":"29","4":"17"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"op":4,"ar":5,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"44"}},{"t":"case","label":"Vt. Yankee v. Nat. Res. Def. Council","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"op":10,"ar":2,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 25, 30, 42, 49","3":"4"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/42/2201","subs":["(b)"],"by":{"0":"19"}},{"t":"usc","label":"42 U.S.C. § 4321","url":"https://www.law.cornell.edu/uscode/text/42/4321","stext":{"head":"§4321. Congressional declaration of purpose","paras":[[0,"The purposes of this chapter are: To declare a national policy which will encourage productive and enjoyable harmony between man and his environment; to promote efforts which will prevent or eliminate damage to the environment and biosphere and stimulate the health and welfare of man; to enrich the understanding of the ecological systems and natural resources important to the Nation; and to establish a Council on Environmental Quality."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4321?type=usc&year=mostrecent&link-type=html"},"head":"§4321. Congressional declaration of purpose","tname":"The Public Health and Welfare","by":{"0":"1, 3","1":"2, 2, 16, 34","2":"4"}},{"t":"usc","label":"42 U.S.C. § 4332","url":"https://www.law.cornell.edu/uscode/text/42/4332","subs":["(2)(C)(1975)","(2)(C)(2019)","(2)(C)","(2)(C)(i)(1970)","(2)(C)(i)","(2)(C)(ii)(1970)","(2)(C)(ii)","(1)","(2)(A)","(2)(B)","(2)(C)(iii)","(2)(C)(iv)","(2)(C)(v)"],"stext":{"head":"§4332. Cooperation of agencies; reports; availability of information; recommendations; international and national coordination of efforts","paras":[[0,"The Congress authorizes and directs that, to the fullest extent possible: (1) the policies, regulations, and public laws of the United States shall be interpreted and administered in accordance with the policies set forth in this chapter, and (2) all agencies of the Federal Government shall—"],[1,"(A) utilize a systematic, interdisciplinary approach which will ensure the integrated use of the natural and social sciences and the environmental design arts in planning and in decisionmaking which may have an impact on man's environment;"],[1,"(B) identify and develop methods and procedures, in consultation with the Council on Environmental Quality established by subchapter II of this chapter, which will ensure that presently unquantified environmental amenities and values may be given appropriate consideration in decisionmaking along with economic and technical considerations;"],[1,"(C) consistent with the provisions of this chapter and except where compliance would be inconsistent with other statutory requirements, include in every recommendation or report on proposals for legislation and other major Federal actions significantly affecting the quality of the human environment, a detailed statement by the responsible official on—"],[2,"(i) reasonably foreseeable environmental effects of the proposed agency action;"],[2,"(ii) any reasonably foreseeable adverse environmental effects which cannot be avoided should the proposal be implemented;"],[2,"(iii) a reasonable range of alternatives to the proposed agency action, including an analysis of any negative environmental impacts of not implementing the proposed agency action in the case of a no action alternative, that are technically and economically feasible, and meet the purpose and need of the proposal;"],[2,"(iv) the relationship between local short-term uses of man's environment and the maintenance and enhancement of long-term productivity; and"],[2,"(v) any irreversible and irretrievable commitments of Federal resources which would be involved in the proposed agency action should it be implemented."],[1,"Prior to making any detailed statement, the head of the lead agency shall consult with and obtain the comments of any Federal agency which has jurisdiction by law or special expertise with respect to any environmental impact involved. Copies of such statement and the comments and views of the appropriate Federal, State, and local agencies, which are authorized to develop and enforce environmental standards, shall be made available to the President, the Council on Environmental Quality and to the public as provided by section 552 of title 5, and shall accompany the proposal through the existing agency review processes;"],[1,"(D) ensure the professional integrity, including scientific integrity, of the discussion and analysis in an environmental document;"],[1,"(E) make use of reliable data and resources in carrying out this chapter;"],[1,"(F) consistent with the provisions of this chapter, study, develop, and describe technically and economically feasible alternatives;"],[1,"(G) any detailed statement required under subparagraph (C) after January 1, 1970, for any major Federal action funded under a program of grants to States shall not be deemed to be legally insufficient solely by reason of having been prepared by a State agency or official, if:"],[2,"(i) the State agency or official has statewide jurisdiction and has the responsibility for such action,"],[2,"(ii) the responsible Federal official furnishes guidance and participates in such preparation,"],[2,"(iii) the responsible Federal official independently evaluates such statement prior to its approval and adoption, and"],[2,"(iv) after January 1, 1976, the responsible Federal official provides early notification to, and solicits the views of, any other State or any Federal land management entity of any action or any alternative thereto which may have significant impacts upon such State or affected Federal land management entity and, if there is any disagreement on such impacts, prepares a written assessment of such impacts and views for incorporation into such detailed statement."],[1,"The procedures in this subparagraph shall not relieve the Federal official of his responsibilities for the scope, objectivity, and content of the entire statement or of any other responsibility under this chapter; and further, this subparagraph does not affect the legal sufficiency of statements prepared by State agencies with less than statewide jurisdiction.1"],[1,"(H) study, develop, and describe appropriate alternatives to recommended courses of action in any proposal which involves unresolved conflicts concerning alternative uses of available resources;"],[1,"(I) consistent with the provisions of this chapter, recognize the worldwide and long-range character of environmental problems and, where consistent with the foreign policy of the United States, lend appropriate support to initiatives, resolutions, and programs designed to maximize international cooperation in anticipating and preventing a decline in the quality of mankind's world environment;"],[1,"(J) make available to States, counties, municipalities, institutions, and individuals, advice and information useful in restoring, maintaining, and enhancing the quality of the environment;"],[1,"(K) initiate and utilize ecological information in the planning and development of resource-oriented projects; and"],[1,"(L) assist the Council on Environmental Quality established by subchapter II of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4332?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§4332. Cooperation of agencies; reports; availability of information; recommendations; international and national coordination of efforts","tname":"The Public Health and Welfare","by":{"0":"28, 20, 4, 33, 2, 18, 29, 33, 34, 29, 49","1":"38, 38, 38, 38, 38","2":"5, 6, 25, 37, 38, 5, 24, 5, 23, 5, 5, 23","3":"32, 41, 32, 4, 4, 18, 20, 23, 31, 37, 39, 45, 10, 20, 29, 29, 10, 20, 29, 37, 29, 25, 18, 24, 18, 24","4":"5, 10"}},{"t":"usc","label":"42 U.S.C. § 4336a","url":"https://www.law.cornell.edu/uscode/text/42/4336a","subs":["(e)(1)","(g)(1)","(a)(3)","(e)","(g)","(e)(2)"],"stext":{"head":"§4336a. Timely and unified Federal reviews","paras":[[0,"(a) Lead agency"],[0,"(1) Designation"],[0,"(A) In general"],[2,"If there are two or more participating Federal agencies, such agencies shall determine, by letter or memorandum, which agency shall be the lead agency based on consideration of the—"],[3,"(i) magnitude of agency's involvement;"],[3,"(ii) project approval or disapproval authority;"],[3,"(iii) expertise concerning the action's environmental effects;"],[3,"(iv) duration of agency's involvement; and"],[3,"(v) sequence of agency's involvement."],[0,"(B) Joint lead agencies"],[2,"In making a determination under subparagraph (A), the participating Federal agencies may appoint such State, Tribal, or local agencies as joint lead agencies as the involved Federal agencies shall determine appropriate. Joint lead agencies shall jointly fulfill the role described in paragraph (2)."],[0,"(2) Role"],[1,"A lead agency shall, with respect to a proposed agency action—"],[2,"(A) supervise the preparation of an environmental document if, with respect to such proposed agency action, there is more than one participating Federal agency;"],[2,"(B) request the participation of each cooperating agency at the earliest practicable time;"],[2,"(C) in preparing an environmental document, give consideration to any analysis or proposal created by a cooperating agency;"],[2,"(D) develop a schedule, in consultation with each cooperating agency, the applicant, and such other entities as the lead agency determines appropriate, for completion of any environmental review, permit, or authorization required to carry out the proposed agency action;"],[2,"(E) if the lead agency determines that a review, permit, or authorization will not be completed in accordance with the schedule developed under subparagraph (D), notify the agency responsible for issuing such review, permit, or authorization of the discrepancy and request that such agency take such measures as such agency determines appropriate to comply with such schedule; and"],[2,"(F) meet with a cooperating agency that requests such a meeting."],[0,"(3) Cooperating agency"],[1,"The lead agency may, with respect to a proposed agency action, designate any Federal, State, Tribal, or local agency that has jurisdiction by law or special expertise with respect to any environmental impact involved in a proposal to serve as a cooperating agency. A cooperating agency may, not later than a date specified in the schedule established by the lead agency, submit comments to the lead agency."],[0,"(4) Request for designation"],[1,"Any Federal, State, Tribal, or local agency or person that is substantially affected by the lack of a designation of a lead agency with respect to a proposed agency action under paragraph (1) may submit a written request for such a designation to a participating Federal agency. An agency that receives a request under this paragraph shall transmit such request to each participating Federal agency and to the Council."],[0,"(5) Council designation"],[0,"(A) Request"],[2,"If the participating Federal agencies are unable to agree on the designation of a lead agency within 45 days of the request under paragraph (4), then the Federal, State, Tribal or local agency or person that is substantially affected by the lack or a designation of a lead agency may request that the Council designate a lead agency. Such request shall consist of—"],[3,"(i) a precise description of the nature and extent of the proposed agency action; and"],[3,"(ii) a detailed statement with respect to each participating Federal agency and each factor listed in paragraph (1) regarding which agency should serve as lead agency."],[0,"(B) Transmission"],[2,"The Council shall transmit a request received under subparagraph (A) to each participating Federal agency."],[0,"(C) Response"],[2,"A participating Federal agency may, not later than 20 days after the date of the submission of a request under subparagraph (A), submit to the Council a response to such request."],[0,"(D) Designation"],[2,"Not later than 40 days after the date of the submission of a request under subparagraph (A), the Council shall designate the lead agency with respect to the relevant proposed agency action."],[0,"(b) One document"],[0,"To the extent practicable, if a proposed agency action will require action by more than one Federal agency and the lead agency has determined that it requires preparation of an environmental document, the lead and cooperating agencies shall evaluate the proposal in a single environmental document."],[0,"(c) Request for public comment"],[0,"Each notice of intent to prepare an environmental impact statement under section 4332 of this title shall include a request for public comment on alternatives or impacts and on relevant information, studies, or analyses with respect to the proposed agency action."],[0,"(d) Statement of purpose and need"],[0,"Each environmental document shall include a statement of purpose and need that briefly summarizes the underlying purpose and need for the proposed agency action."],[0,"(e) Page limits"],[0,"(1) Environmental impact statements"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), an environmental impact statement shall not exceed 150 pages, not including any citations or appendices."],[0,"(B) Extraordinary complexity"],[2,"An environmental impact statement for a proposed agency action of extraordinary complexity shall not exceed 300 pages, not including any citations or appendices."],[0,"(2) Environmental assessments"],[1,"An environmental assessment shall not exceed 75 pages, not including any citations or appendices."],[0,"(f) Sponsor preparation"],[0,"A lead agency shall prescribe procedures to allow a project sponsor to prepare an environmental assessment or an environmental impact statement under the supervision of the agency. Such agency may provide such sponsor with appropriate guidance and assist in the preparation. The lead agency shall independently evaluate the environmental document and shall take responsibility for the contents."],[0,"(g) Deadlines"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), with respect to a proposed agency action, a lead agency shall complete, as applicable—"],[2,"(A) the environmental impact statement not later than the date that is 2 years after the sooner of, as applicable—"],[3,"(i) the date on which such agency determines that section 4332(2)(C) of this title requires the issuance of an environmental impact statement with respect to such action;"],[3,"(ii) the date on which such agency notifies the applicant that the application to establish a right-of-way for such action is complete; and"],[3,"(iii) the date on which such agency issues a notice of intent to prepare the environmental impact statement for such action; and"],[2,"(B) the environmental assessment not later than the date that is 1 year after the sooner of, as applicable—"],[3,"(i) the date on which such agency determines that section 4336(b)(2) of this title requires the preparation of an environmental assessment with respect to such action;"],[3,"(ii) the date on which such agency notifies the applicant that the application to establish a right-of-way for such action is complete; and"],[3,"(iii) the date on which such agency issues a notice of intent to prepare the environmental assessment for such action."],[0,"(2) Delay"],[1,"A lead agency that determines it is not able to meet the deadline described in paragraph (1) may extend such deadline, in consultation with the applicant, to establish a new deadline that provides only so much additional time as is necessary to complete such environmental impact statement or environmental assessment."],[0,"(3) Petition to court"],[0,"(A) Right to petition"],[2,"A project sponsor may obtain a review of an alleged failure by an agency to act in accordance with an applicable deadline under this section by filing a written petition with a court of competent jurisdiction seeking an order under subparagraph (B)."],[0,"(B) Court order"],[2,"If a court of competent jurisdiction finds that an agency has failed to act in accordance with an applicable deadline, the court shall set a schedule and deadline for the agency to act as soon as practicable, which shall not exceed 90 days from the date on which the order of the court is issued, unless the court determines a longer time period is necessary to comply with applicable law."],[0,"(h) Report"],[0,"(1) In general"],[1,"The head of each lead agency shall annually submit to the Committee on Natural Resources of the House of Representatives and the Committee on Environment and Public Works of the Senate a report that—"],[2,"(A) identifies any environmental assessment and environmental impact statement that such lead agency did not complete by the deadline described in subsection (g); and"],[2,"(B) provides an explanation for any failure to meet such deadline."],[0,"(2) Inclusions"],[1,"Each report submitted under paragraph (1) shall identify, as applicable—"],[2,"(A) the office, bureau, division, unit, or other entity within the Federal agency responsible for each such environmental assessment and environmental impact statement;"],[2,"(B) the date on which—"],[3,"(i) such lead agency notified the applicant that the application to establish a right-of-way for the major Federal action is complete;"],[3,"(ii) such lead agency began the scoping for the major Federal action; or"],[3,"(iii) such lead agency issued a notice of intent to prepare the environmental assessment or environmental impact statement for the major Federal action; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4336a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4336a. Timely and unified Federal reviews","tname":"The Public Health and Welfare","by":{"0":"29, 29","1":"38, 32","2":"25, 25","3":"43, 31, 37, 10, 10, 10"}},{"t":"usc","label":"49 U.S.C. § 103","url":"https://www.law.cornell.edu/uscode/text/49/103","subs":["(d)"],"by":{"0":"10, 47"}},{"t":"usc","label":"49 U.S.C. § 10901","url":"https://www.law.cornell.edu/uscode/text/49/10901","subs":["(c)","(b)","(a)"],"stext":{"head":"§10901. Authorizing construction and operation of railroad lines","paras":[[0,"(a) A person may—"],[1,"(1) construct an extension to any of its railroad lines;"],[1,"(2) construct an additional railroad line;"],[1,"(3) provide transportation over, or by means of, an extended or additional railroad line; or"],[1,"(4) in the case of a person other than a rail carrier, acquire a railroad line or acquire or operate an extended or additional railroad line,"],[0,"only if the Board issues a certificate authorizing such activity under subsection (c)."],[0,"(b) A proceeding to grant authority under subsection (a) of this section begins when an application is filed. On receiving the application, the Board shall give reasonable public notice, including notice to the Governor of any affected State, of the beginning of such proceeding."],[0,"(c) The Board shall issue a certificate authorizing activities for which such authority is requested in an application filed under subsection (b) unless the Board finds that such activities are inconsistent with the public convenience and necessity. Such certificate may approve the application as filed, or with modifications, and may require compliance with conditions (other than labor protection conditions) the Board finds necessary in the public interest."],[0,"(d)(1) When a certificate has been issued by the Board under this section authorizing the construction or extension of a railroad line, no other rail carrier may block any construction or extension authorized by such certificate by refusing to permit the carrier to cross its property if—"],[1,"(A) the construction does not unreasonably interfere with the operation of the crossed line;"],[1,"(B) the operation does not materially interfere with the operation of the crossed line; and"],[1,"(C) the owner of the crossing line compensates the owner of the crossed line."],[0,"(2) If the parties are unable to agree on the terms of operation or the amount of payment for purposes of paragraph (1) of this subsection, either party may submit the matters in dispute to the Board for determination. The Board shall make a determination under this paragraph within 120 days after the dispute is submitted for determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/10901?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§10901. Authorizing construction and operation of railroad lines","tname":"Transportation","by":{"0":"10, 13, 32, 48","1":"4, 4, 4","2":"7, 7","3":"12, 12","4":"9"}},{"t":"usc","label":"49 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/49/1301","subs":["(b)(2)"],"by":{"0":"10"}},{"t":"law","label":"Pub. L. No. 118-5","url":"https://www.govinfo.gov/link/plaw/118/public/5","by":{"0":"7, 8","1":"3, 17, 22","2":"5","3":"3"}},{"t":"reg","label":"40 C.F.R. § 1508.8","url":"https://www.ecfr.gov/current/title-40/section-1508.8","subs":["(a)","(b)"],"by":{"0":"39","2":"6, 23","3":"26, 8, 8"}},{"t":"case","label":"Akron, Canton & Youngstown R.R. v. ICC","cite":"611 F.2d 1162","y":1979,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/611/1162/","by":{"1":"4"}},{"t":"case","label":"Bank of Am. Corp. v. City of Miami","cite":"581 U.S. 189","y":2017,"id":"2016/15-1111","sc":1,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"1":"36, 37","2":"35"}},{"t":"case","label":"Riffin v. Surface Transp. Bd.","cite":"733 F.3d 340","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/733/340/","op":1,"by":{"1":"4"}},{"t":"case","label":"Rocky Mountain Wild v. Bernhardt","cite":"506 F. Supp. 3d 1169","y":2020,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/506/1169/","by":{"1":"43"}},{"t":"case","label":"Sierra Club v. FERC","cite":"827 F.3d 36","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/827/36/","sum":"Finding that the Federal Energy Regulatory Commission was not required “to address the indirect effects of the anticipated export of natural gas” as part of its NEPA analysis of the authorization of new natural gas facilities because “the Department of Energy, not the Commission, has sole authority to license the export of any natural gas going through the [new] facilities”.","sumSrc":"brief:1","by":{"1":"26","2":"30, 32","3":"40"}},{"t":"case","label":"Southern Utah Wilderness Alliance v. United States Dep’t of the Interior","cite":"2016 WL 6909036","y":2016,"court":"D. Utah Oct. 3","by":{"1":"43"}},{"t":"case","label":"WildEarth Guardians v. United States Forest Serv.","cite":"2021 WL 409827","y":2021,"court":"D. Utah Feb. 5","by":{"1":"43"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(a)(2)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"1":"28"}},{"t":"usc","label":"42 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/42/3601","by":{"1":"36"}},{"t":"usc","label":"45 U.S.C. § 51","url":"https://www.law.cornell.edu/uscode/text/45/51","by":{"1":"23"}},{"t":"usc","label":"49 U.S.C. § 10101","url":"https://www.law.cornell.edu/uscode/text/49/10101","subs":["(8)","(14)","(4)"],"stext":{"head":"§10101. Rail transportation policy","paras":[[0,"In regulating the railroad industry, it is the policy of the United States Government—"],[1,"(1) to allow, to the maximum extent possible, competition and the demand for services to establish reasonable rates for transportation by rail;"],[1,"(2) to minimize the need for Federal regulatory control over the rail transportation system and to require fair and expeditious regulatory decisions when regulation is required;"],[1,"(3) to promote a safe and efficient rail transportation system by allowing rail carriers to earn adequate revenues, as determined by the Board;"],[1,"(4) to ensure the development and continuation of a sound rail transportation system with effective competition among rail carriers and with other modes, to meet the needs of the public and the national defense;"],[1,"(5) to foster sound economic conditions in transportation and to ensure effective competition and coordination between rail carriers and other modes;"],[1,"(6) to maintain reasonable rates where there is an absence of effective competition and where rail rates provide revenues which exceed the amount necessary to maintain the rail system and to attract capital;"],[1,"(7) to reduce regulatory barriers to entry into and exit from the industry;"],[1,"(8) to operate transportation facilities and equipment without detriment to the public health and safety;"],[1,"(9) to encourage honest and efficient management of railroads;"],[1,"(10) to require rail carriers, to the maximum extent practicable, to rely on individual rate increases, and to limit the use of increases of general applicability;"],[1,"(11) to encourage fair wages and safe and suitable working conditions in the railroad industry;"],[1,"(12) to prohibit predatory pricing and practices, to avoid undue concentrations of market power, and to prohibit unlawful discrimination;"],[1,"(13) to ensure the availability of accurate cost information in regulatory proceedings, while minimizing the burden on rail carriers of developing and maintaining the capability of providing such information;"],[1,"(14) to encourage and promote energy conservation; and"],[1,"(15) to provide for the expeditious handling and resolution of all proceedings required or permitted to be brought under this part."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/10101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§10101. Rail transportation policy","tname":"Transportation","by":{"1":"3, 5","2":"7, 8, 8","3":"12, 12, 12"}},{"t":"usc","label":"49 U.S.C. § 10501","url":"https://www.law.cornell.edu/uscode/text/49/10501","subs":["(b)(2)","(c)","(b)(1)"],"stext":{"head":"§10501. General jurisdiction","paras":[[0,"(a)(1) Subject to this chapter, the Board has jurisdiction over transportation by rail carrier that is—"],[1,"(A) only by railroad; or"],[1,"(B) by railroad and water, when the transportation is under common control, management, or arrangement for a continuous carriage or shipment."],[0,"(2) Jurisdiction under paragraph (1) applies only to transportation in the United States between a place in—"],[1,"(A) a State and a place in the same or another State as part of the interstate rail network;"],[1,"(B) a State and a place in a territory or possession of the United States;"],[1,"(C) a territory or possession of the United States and a place in another such territory or possession;"],[1,"(D) a territory or possession of the United States and another place in the same territory or possession;"],[1,"(E) the United States and another place in the United States through a foreign country; or"],[1,"(F) the United States and a place in a foreign country."],[0,"(b) The jurisdiction of the Board over—"],[1,"(1) transportation by rail carriers, and the remedies provided in this part with respect to rates, classifications, rules (including car service, interchange, and other operating rules), practices, routes, services, and facilities of such carriers; and"],[1,"(2) the construction, acquisition, operation, abandonment, or discontinuance of spur, industrial, team, switching, or side tracks, or facilities, even if the tracks are located, or intended to be located, entirely in one State,"],[0,"is exclusive. Except as otherwise provided in this part, the remedies provided under this part with respect to regulation of rail transportation are exclusive and preempt the remedies provided under Federal or State law."],[0,"(c)(1) In this subsection—"],[1,"(A) the term \"local governmental authority\"—"],[2,"(i) has the same meaning given that term by section 5302 of this title; and"],[2,"(ii) includes a person or entity that contracts with the local governmental authority to provide transportation services; and"],[1,"(B) the term \"public transportation\" means transportation services described in section 5302 of this title that are provided by rail."],[0,"(2) Except as provided in paragraph (3), the Board does not have jurisdiction under this part over—"],[1,"(A) public transportation provided by a local government authority; or"],[1,"(B) a solid waste rail transfer facility as defined in section 10908 of this title, except as provided under sections 10908 and 10909 of this title."],[0,"(3)(A) Notwithstanding paragraph (2) of this subsection, a local governmental authority, described in paragraph (2), is subject to applicable laws of the United States related to—"],[1,"(i) safety;"],[1,"(ii) the representation of employees for collective bargaining; and"],[1,"(iii) employment, retirement, annuity, and unemployment systems or other provisions related to dealings between employees and employers."],[0,"(B) The Board has jurisdiction under sections 11102 and 11103 of this title over transportation provided by a local governmental authority only if the Board finds that such governmental authority meets all of the standards and requirements for being a rail carrier providing transportation subject to the jurisdiction of the Interstate Commerce Commission that were in effect immediately before January 1, 1996. The enactment of the ICC Termination Act of 1995 shall neither expand nor contract coverage of employees and employers by the Railway Labor Act, the Railroad Retirement Act of 1974, the Railroad Retirement Tax Act, and the Railroad Unemployment Insurance Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/10501?type=usc&year=mostrecent&link-type=html"},"head":"§10501. General jurisdiction","tname":"Transportation","by":{"1":"9, 42, 4, 4","2":"7, 7"}},{"t":"usc","label":"49 U.S.C. § 10502","url":"https://www.law.cornell.edu/uscode/text/49/10502","subs":["(a)","(a)(1)"],"stext":{"head":"§10502. Authority to exempt rail carrier transportation","paras":[[0,"(a) In a matter related to a rail carrier providing transportation subject to the jurisdiction of the Board under this part, the Board, to the maximum extent consistent with this part, shall exempt a person, class of persons, or a transaction or service whenever the Board finds that the application in whole or in part of a provision of this part—"],[1,"(1) is not necessary to carry out the transportation policy of section 10101 of this title; and"],[1,"(2) either—"],[2,"(A) the transaction or service is of limited scope; or"],[2,"(B) the application in whole or in part of the provision is not needed to protect shippers from the abuse of market power."],[0,"(b) The Board may, where appropriate, begin a proceeding under this section on its own initiative or on application by the Secretary of Transportation or an interested party. The Board shall, within 90 days after receipt of any such application, determine whether to begin an appropriate proceeding. If the Board decides not to begin a class exemption proceeding, the reasons for the decision shall be published in the Federal Register. Any proceeding begun as a result of an application under this subsection shall be completed within 9 months after it is begun."],[0,"(c) The Board may specify the period of time during which an exemption granted under this section is effective."],[0,"(d) The Board may revoke an exemption, to the extent it specifies, when it finds that application in whole or in part of a provision of this part to the person, class, or transportation is necessary to carry out the transportation policy of section 10101 of this title. The Board shall, within 90 days after receipt of a request for revocation under this subsection, determine whether to begin an appropriate proceeding. If the Board decides not to begin a proceeding to revoke a class exemption, the reasons for the decision shall be published in the Federal Register. Any proceeding begun as a result of a request under this subsection shall be completed within 9 months after it is begun."],[0,"(e) No exemption order issued pursuant to this section shall operate to relieve any rail carrier from an obligation to provide contractual terms for liability and claims which are consistent with the provisions of section 11706 of this title. Nothing in this subsection or section 11706 of this title shall prevent rail carriers from offering alternative terms nor give the Board the authority to require any specific level of rates or services based upon the provisions of section 11706 of this title."],[0,"(f) The Board may exercise its authority under this section to exempt transportation that is provided by a rail carrier as part of a continuous intermodal movement."],[0,"(g) The Board may not exercise its authority under this section to relieve a rail carrier of its obligation to protect the interests of employees as required by this part."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/10502?type=usc&year=mostrecent&link-type=html"},"head":"§10502. Authority to exempt rail carrier transportation","tname":"Transportation","by":{"1":"4, 4, 4","2":"10, 7","3":"12"}},{"t":"usc","label":"49 U.S.C. § 11101","url":"https://www.law.cornell.edu/uscode/text/49/11101","stext":{"head":"§11101. Common carrier transportation, service, and rates","paras":[[0,"(a) A rail carrier providing transportation or service subject to the jurisdiction of the Board under this part shall provide the transportation or service on reasonable request. A rail carrier shall not be found to have violated this section because it fulfills its reasonable commitments under contracts authorized under section 10709 of this title before responding to reasonable requests for service. Commitments which deprive a carrier of its ability to respond to reasonable requests for common carrier service are not reasonable."],[0,"(b) A rail carrier shall also provide to any person, on request, the carrier's rates and other service terms. The response by a rail carrier to a request for the carrier's rates and other service terms shall be—"],[1,"(1) in writing and forwarded to the requesting person promptly after receipt of the request; or"],[1,"(2) promptly made available in electronic form."],[0,"(c) A rail carrier may not increase any common carrier rates or change any common carrier service terms unless 20 days have expired after written or electronic notice is provided to any person who, within the previous 12 months—"],[1,"(1) has requested such rates or terms under subsection (b); or"],[1,"(2) has made arrangements with the carrier for a shipment that would be subject to such increased rates or changed terms."],[0,"(d) With respect to transportation of agricultural products, in addition to the requirements of subsections (a), (b), and (c), a rail carrier shall publish, make available, and retain for public inspection its common carrier rates, schedules of rates, and other service terms, and any proposed and actual changes to such rates and service terms. For purposes of this subsection, agricultural products shall include grain as defined in section 3 of the United States Grain Standards Act (7 U.S.C. 75) and all products thereof, and fertilizer."],[0,"(e) A rail carrier shall provide transportation or service in accordance with the rates and service terms, and any changes thereto, as published or otherwise made available under subsection (b), (c), or (d)."],[0,"(f) The Board shall, by regulation, establish rules to implement this section. The regulations shall provide for immediate disclosure and dissemination of rates and service terms, including classifications, rules, and practices, and their effective dates. Final regulations shall be adopted by the Board not later than 180 days after January 1, 1996."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/11101?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§11101. Common carrier transportation, service, and rates","tname":"Transportation","by":{"1":"4"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","by":{"1":"36"}},{"t":"usc","label":"42 U.S.C. § 4331","url":"https://www.law.cornell.edu/uscode/text/42/4331","subs":["(a)","(b)","(b)(1)"],"stext":{"head":"§4331. Congressional declaration of national environmental policy","paras":[[0,"(a) The Congress, recognizing the profound impact of man's activity on the interrelations of all components of the natural environment, particularly the profound influences of population growth, high-density urbanization, industrial expansion, resource exploitation, and new and expanding technological advances and recognizing further the critical importance of restoring and maintaining environmental quality to the overall welfare and development of man, declares that it is the continuing policy of the Federal Government, in cooperation with State and local governments, and other concerned public and private organizations, to use all practicable means and measures, including financial and technical assistance, in a manner calculated to foster and promote the general welfare, to create and maintain conditions under which man and nature can exist in productive harmony, and fulfill the social, economic, and other requirements of present and future generations of Americans."],[0,"(b) In order to carry out the policy set forth in this chapter, it is the continuing responsibility of the Federal Government to use all practicable means, consistent with other essential considerations of national policy, to improve and coordinate Federal plans, functions, programs, and resources to the end that the Nation may—"],[1,"(1) fulfill the responsibilities of each generation as trustee of the environment for succeeding generations;"],[1,"(2) assure for all Americans safe, healthful, productive, and esthetically and culturally pleasing surroundings;"],[1,"(3) attain the widest range of beneficial uses of the environment without degradation, risk to health or safety, or other undesirable and unintended consequences;"],[1,"(4) preserve important historic, cultural, and natural aspects of our national heritage, and maintain, wherever possible, an environment which supports diversity and variety of individual choice;"],[1,"(5) achieve a balance between population and resource use which will permit high standards of living and a wide sharing of life's amenities; and"],[1,"(6) enhance the quality of renewable resources and approach the maximum attainable recycling of depletable resources."],[0,"(c) The Congress recognizes that each person should enjoy a healthful environment and that each person has a responsibility to contribute to the preservation and enhancement of the environment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4331?type=usc&year=mostrecent&link-type=html"},"head":"§4331. Congressional declaration of national environmental policy","tname":"The Public Health and Welfare","by":{"1":"2","3":"3, 24, 3, 32, 24"}},{"t":"usc","label":"42 U.S.C. § 4336","url":"https://www.law.cornell.edu/uscode/text/42/4336","subs":["(a)(3)","(a)(4)"],"stext":{"head":"§4336. Procedure for determination of level of review","paras":[[0,"(a) Threshold determinations"],[0,"An agency is not required to prepare an environmental document with respect to a proposed agency action if—"],[1,"(1) the proposed agency action is not a final agency action within the meaning of such term in chapter 5 of title 5;"],[1,"(2) the proposed agency action is excluded pursuant to one of the agency's categorical exclusions, another agency's categorical exclusions consistent with section 4336c of this title, or another provision of law;"],[1,"(3) the preparation of such document would clearly and fundamentally conflict with the requirements of another provision of law; or"],[1,"(4) the proposed agency action is a nondiscretionary action with respect to which such agency does not have authority to take environmental factors into consideration in determining whether to take the proposed action."],[0,"(b) Levels of review"],[0,"(1) Environmental impact statement"],[1,"An agency shall issue an environmental impact statement with respect to a proposed agency action requiring an environmental document that has a reasonably foreseeable significant effect on the quality of the human environment."],[0,"(2) Environmental assessment"],[1,"An agency shall prepare an environmental assessment with respect to a proposed agency action that does not have a reasonably foreseeable significant effect on the quality of the human environment, or if the significance of such effect is unknown, unless the agency finds that the proposed agency action is excluded pursuant to one of the agency's categorical exclusions, another agency's categorical exclusions consistent with section 4336c of this title, or another provision of law. Such environmental assessment shall be a concise public document prepared by a Federal agency to set forth the basis of such agency's finding of no significant impact or determination that an environmental impact statement is necessary."],[0,"(3) Sources of information"],[1,"In making a determination under this subsection, an agency—"],[2,"(A) may make use of any reliable data source; and"],[2,"(B) is not required to undertake new scientific or technical research unless the new scientific or technical research is essential to a reasoned choice among alternatives, and the overall costs and time frame of obtaining it are not unreasonable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4336?type=usc&year=mostrecent&link-type=html"},"head":"§4336. Procedure for determination of level of review","tname":"The Public Health and Welfare","by":{"1":"38","3":"30, 20, 30"}},{"t":"usc","label":"42 U.S.C. § 4336e","url":"https://www.law.cornell.edu/uscode/text/42/4336e","subs":["(10)","(10)(B)","(13)"],"stext":{"head":"§4336e. Definitions","paras":[[0,"In this subchapter:"],[0,"(1) Categorical exclusion"],[1,"The term \"categorical exclusion\" means a category of actions that a Federal agency has determined normally does not significantly affect the quality of the human environment within the meaning of section 4332(2)(C) of this title."],[0,"(2) Cooperating agency"],[1,"The term \"cooperating agency\" means any Federal, State, Tribal, or local agency that has been designated as a cooperating agency under section 4336a(a)(3) of this title."],[0,"(3) Council"],[1,"The term \"Council\" means the Council on Environmental Quality established in subchapter II."],[0,"(4) Environmental assessment"],[1,"The term \"environmental assessment\" means an environmental assessment prepared under section 4336(b)(2) of this title."],[0,"(5) Environmental document"],[1,"The term \"environmental document\" means an environmental impact statement, an environmental assessment, or a finding of no significant impact."],[0,"(6) Environmental impact statement"],[1,"The term \"environmental impact statement\" means a detailed written statement that is required by section 4332(2)(C) of this title."],[0,"(7) Finding of no significant impact"],[1,"The term \"finding of no significant impact\" means a determination by a Federal agency that a proposed agency action does not require the issuance of an environmental impact statement."],[0,"(8) Participating Federal agency"],[1,"The term \"participating Federal agency\" means a Federal agency participating in an environmental review or authorization of an action."],[0,"(9) Lead agency"],[1,"The term \"lead agency\" means, with respect to a proposed agency action—"],[2,"(A) the agency that proposed such action; or"],[2,"(B) if there are 2 or more involved Federal agencies with respect to such action, the agency designated under section 4336a(a)(1) of this title."],[0,"(10) Major Federal action"],[0,"(A) In general"],[2,"The term \"major Federal action\" means an action that the agency carrying out such action determines is subject to substantial Federal control and responsibility."],[0,"(B) Exclusion"],[2,"The term \"major Federal action\" does not include—"],[3,"(i) a non-Federal action—"],[4,"(I) with no or minimal Federal funding; or"],[4,"(II) with no or minimal Federal involvement where a Federal agency cannot control the outcome of the project;"],[3,"(ii) funding assistance solely in the form of general revenue sharing funds which do not provide Federal agency compliance or enforcement responsibility over the subsequent use of such funds;"],[3,"(iii) loans, loan guarantees, or other forms of financial assistance where a Federal agency does not exercise sufficient control and responsibility over the subsequent use of such financial assistance or the effect of the action;"],[3,"(iv) business loan guarantees provided by the Small Business Administration pursuant to section 7(a) or (b) and 1 of the Small Business Act ( U.S.C. 636(a)),2 or title V of the Small Business Investment Act of 1958 (15 U.S.C. 695 et seq.);"],[3,"(v) bringing judicial or administrative civil or criminal enforcement actions;"],[3,"(vi) extraterritorial activities or decisions, which means agency activities or decisions with effects located entirely outside of the jurisdiction of the United States; or"],[3,"(vii) activities or decisions that are non-discretionary and made in accordance with the agency's statutory authority."],[0,"(11) Programmatic environmental document"],[1,"The term \"programmatic environmental document\" means an environmental impact statement or environmental assessment analyzing all or some of the environmental effects of a policy, program, plan, or group of related actions."],[0,"(12) Proposal"],[1,"The term \"proposal\" means a proposed action at a stage when an agency has a goal, is actively preparing to make a decision on one or more alternative means of accomplishing that goal, and can meaningfully evaluate its effects."],[0,"(13) Special expertise"],[1,"The term \"special expertise\" means statutory responsibility, agency mission, or related program experience."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4336e?type=usc&year=mostrecent&link-type=html"},"head":"§4336e. Definitions","tname":"The Public Health and Welfare","by":{"1":"38","2":"25","3":"10, 32"}},{"t":"usc","label":"42 U.S.C. § 4342","url":"https://www.law.cornell.edu/uscode/text/42/4342","stext":{"head":"§4342. Establishment; membership; Chairman; appointments","paras":[[0,"There is created in the Executive Office of the President a Council on Environmental Quality (hereinafter referred to as the \"Council\"). The Council shall be composed of three members who shall be appointed by the President to serve at his pleasure, by and with the advice and consent of the Senate. The President shall designate one of the members of the Council to serve as Chairman. Each member shall be a person who, as a result of his training, experience, and attainments, is exceptionally well qualified to analyze and interpret environmental trends and information of all kinds; to appraise programs and activities of the Federal Government in the light of the policy set forth in subchapter I of this chapter; to be conscious of and responsive to the scientific, economic, social, esthetic, and cultural needs and interests of the Nation; and to formulate and recommend national policies to promote the improvement of the quality of the environment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4342?type=usc&year=mostrecent&link-type=html"},"head":"§4342. Establishment; membership; Chairman; appointments","tname":"The Public Health and Welfare","by":{"1":"3","3":"5"}},{"t":"reg","label":"49 C.F.R. § 1151.2","url":"https://www.ecfr.gov/current/title-49/section-1151.2","by":{"1":"4"}},{"t":"reg","label":"43 Fed. Reg. 55,978","url":"https://www.govinfo.gov/link/fr/43/55978","by":{"1":"3, 22","2":"6, 24","3":"8","4":"13"}},{"t":"reg","label":"85 Fed. Reg. 43,304","url":"https://www.govinfo.gov/link/fr/85/43304","by":{"1":"3, 22, 29","2":"6, 15, 27"}},{"t":"reg","label":"87 Fed. Reg. 23,453","url":"https://www.govinfo.gov/link/fr/87/23453","by":{"1":"23, 24, 27, 30","2":"23, 24","3":"9, 10, 38"}},{"t":"case","label":"Ark. Wildlife Fed’n v. U.S. Army Corps of Engineers","cite":"431 F.3d 1096","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/431/1096/","by":{"2":"27"}},{"t":"case","label":"City of Shoreacres v. Waterworth","cite":"420 F.3d 440","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/420/440/","by":{"2":"33"}},{"t":"case","label":"Dine Citizens Against Ruining Our Env’t v. Bernhardt","cite":"923 F.3d 831","y":2019,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/923/831/","by":{"2":"27"}},{"t":"case","label":"EarthReports, Inc. v. FERC","cite":"828 F.3d 949","y":2016,"court":"D.C. Circ.","url":"https://www.courtlistener.com/c/F.3d/828/949/","by":{"2":"27"}},{"t":"case","label":"Hemi Grp., LLC v. City of N.Y.","cite":"559 U.S. 1","y":2010,"id":"2009/08-969","sc":1,"sum":"The Court held that the city of New York had standing to sue out-of-state cigarette vendors under the Racketeer Influenced and Corrupt Organizations Act.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Husted v. A. Philip Randolph Inst.","cite":"584 U.S. 756","y":2018,"id":"2017/16-980","sc":1,"sum":"A case in which the Court upheld Ohio's list-maintenance process against a challenge under under National Voter Registration Act of 1993 (NVRA) and the Help America Vote Act of 2002 (HAVA).","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"La. Crawfish Producers Ass’n-W v. Rowan","cite":"463 F.3d 352","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/463/352/","by":{"2":"27"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"op":2,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Scientists’ Inst. for Pub. Info., Inc. v. Atomic Energy Comm’n","cite":"481 F.2d 1079","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/481/1079/","by":{"2":"23","3":"7, 8, 25, 26","4":"12"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"ar":1,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"50"}},{"t":"case","label":"Sierra Club v. Marsh","cite":"976 F.2d 763","y":1992,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/976/763/","sum":"Holding that light-dry industry development was a reasonably foreseeable effect of a new cargo port.","sumSrc":"brief:3","by":{"2":"17, 26, 27, 28","3":"28"}},{"t":"case","label":"Solar Energy Indus. Ass’n v. FERC","cite":"80 F.4th 956","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/80/956/","by":{"2":"27"}},{"t":"case","label":"Swain v. Brinegar","cite":"542 F.2d 364","y":1976,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/542/364/","by":{"2":"23","3":"8"}},{"t":"case","label":"Vill. of Bensenville v. FAA","cite":"457 F.3d 52","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/457/52/","by":{"2":"32"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(a)"],"by":{"2":"30"}},{"t":"usc","label":"49 U.S.C. § 10902","url":"https://www.law.cornell.edu/uscode/text/49/10902","subs":["(a)"],"by":{"2":"7"}},{"t":"law","label":"Pub. L. No. 91-190","url":"https://www.govinfo.gov/link/statute/83/852","by":{"2":"4","3":"3"}},{"t":"reg","label":"40 C.F.R. § 1501.7","url":"https://www.ecfr.gov/current/title-40/section-1501.7","subs":["(a)(1)","(c)"],"by":{"2":"6, 6","3":"9"}},{"t":"reg","label":"40 C.F.R. § 1501.8","url":"https://www.ecfr.gov/current/title-40/section-1501.8","subs":["(a)","(b)(3)"],"by":{"2":"6, 7, 7, 38"}},{"t":"reg","label":"40 C.F.R. § 1502.1","url":"https://www.ecfr.gov/current/title-40/section-1502.1","subs":["(a)","(b)"],"by":{"2":"5, 5"}},{"t":"reg","label":"40 C.F.R. § 1502.21","url":"https://www.ecfr.gov/current/title-40/section-1502.21","subs":["(c)"],"by":{"2":"15, 45"}},{"t":"reg","label":"40 C.F.R. § 1502.22","url":"https://www.ecfr.gov/current/title-40/section-1502.22","subs":["(b)"],"by":{"2":"40, 15","3":"8"}},{"t":"reg","label":"40 C.F.R. § 1508.1","url":"https://www.ecfr.gov/current/title-40/section-1508.1","subs":["(g)","(i)","(aa)","(ii)","(g)(2)","(i)(3)"],"by":{"2":"23, 24, 24, 6, 6, 17, 27","3":"9, 26, 14, 9, 10, 18, 23, 26"}},{"t":"reg","label":"49 C.F.R. § 1105.6","url":"https://www.ecfr.gov/current/title-49/section-1105.6","subs":["(a)","(b)"],"by":{"2":"8, 8"}},{"t":"reg","label":"49 C.F.R. § 1105.7","url":"https://www.ecfr.gov/current/title-49/section-1105.7","subs":["(e)","(e)(5)(i)","(e)(11)(v)"],"by":{"2":"8, 47, 9, 8, 9"}},{"t":"reg","label":"49 C.F.R. § 1150.1","url":"https://www.ecfr.gov/current/title-49/section-1150.1","by":{"2":"7"}},{"t":"reg","label":"84 Fed. Reg. 68,274","url":"https://www.govinfo.gov/link/fr/84/68274","by":{"2":"10"}},{"t":"reg","label":"85 Fed. Reg. 1,684","url":"https://www.govinfo.gov/link/fr/85/1684","by":{"2":"27"}},{"t":"reg","label":"89 Fed. Reg. 35,442","url":"https://www.govinfo.gov/link/fr/89/35442","by":{"2":"28","3":"38"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"3":"24"}},{"t":"case","label":"Barnes v. U.S. Dep’t of Transp.","cite":"655 F.3d 1124","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/1124/","sum":"Holding that a conclusion that a “major hub airport” runway would not induce growth “strain[ed] credulity” given the record.","sumSrc":"brief:3","by":{"3":"27"}},{"t":"case","label":"Bissonette v. LePage Bakeries Park St., LLC","cite":"601 U.S. 246","y":2024,"id":"2023/23-51","sc":1,"sum":"A transportation worker need not work in the transportation industry to be exempt from coverage under §1 of the Federal Arbitration Act, 9 U. S. C. §1 et seq.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"47"}},{"t":"case","label":"Citizens Organized to Defend Env’t, Inc. v. Volpe","cite":"353 F. Supp. 520","y":1972,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./353/520/","sum":"Noting that a highway project that grants a right to use the highway to facilitate strip mining would require studying the project’s impact on the environmental effects of the mining.","sumSrc":"brief:3","by":{"3":"5"}},{"t":"case","label":"City of Davis v. Coleman","cite":"521 F.2d 661","y":1975,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/521/661/","sum":"Holding that an agency needed to consider the effects of industrial development a proposed highway interchange would spur.","sumSrc":"brief:3","by":{"3":"5"}},{"t":"case","label":"City of Los Angeles v. Fed. Aviation Admin.","cite":"138 F.3d 806","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/138/806/","sum":"Upholding a decision not to study growth-inducing effects because demand did not turn on “how nifty the [expanded] terminal is”.","sumSrc":"brief:3","by":{"3":"27"}},{"t":"case","label":"Coinbase, Inc. v. Suski","cite":"144 S. Ct. 1186","y":2024,"id":"2023/23-3","sc":1,"sum":"Where parties have agreed to two contracts—one sending arbitrability disputes to arbitration, and the other either explicitly or implicitly sending arbitrability disputes to the courts—a court must decide which contract governs.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"44"}},{"t":"case","label":"Conservation Council of N.C. v. Constanzo","cite":"398 F. Supp. 653","y":1975,"court":"E.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Supp./398/653/","by":{"3":"5"}},{"t":"case","label":"Exxon Co. v. Sofec., Inc.","cite":"517 U.S. 830","y":1996,"id":"1995/95-129","sc":1,"sum":"The Court held that a plaintiff in admiralty that is the superseding cause of its own injury, and thus the sole, proximate cause, cannot recover part of its damages from tort-feasors or contracting partners whose blameworthy actions were causes in fact of the injury.","sumSrc":"Oyez","by":{"3":"38, 40"}},{"t":"case","label":"Flint Ridge Dev. Co. v. Scenic Rivers Ass’n of Okla.","cite":"426 U.S. 776","y":1976,"id":"1975/75-510","sc":1,"sum":"The Interstate Land Sales Full Disclosure Act (Disclosure Act), which is designed to prevent false and deceptive practices in the interstate sale of unimproved tracts of land by requiring developers to disclose information needed by potential purchasers, requires a developer to register a subdivision by filing with the Department of Housing and Urban Development (HUD) a statement of record containing information …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"24, 29"}},{"t":"case","label":"Food & Water Watch v. FERC","cite":"104 F.4th 336","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/104/336/","sum":"Holding that the agency “reasonably concluded” that it need not assess “effects caused by extracting natural gas” given uncertainty over the number and location of wells.","sumSrc":"brief:3","by":{"3":"28"}},{"t":"case","label":"George v. McDonough","cite":"596 U.S. 740","y":2022,"id":"2021/21-234","sc":1,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"40"}},{"t":"case","label":"Headwaters, Inc. v. Bureau of Land Mgmt., Medford Dist.","cite":"914 F.2d 1174","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/914/1174/","sum":"Holding that “no evidence” rendered the “conceivable” possibility that a road project would increase logging “more than speculation”.","sumSrc":"brief:3","by":{"3":"28"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"op":3,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"19, 26","4":"13"}},{"t":"case","label":"Louisiana v. Fed. Power Comm’n","cite":"503 F.2d 844","y":1974,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/503/844/","op":4,"ar":5,"by":{"3":"8, 26","4":"11"}},{"t":"case","label":"Nat. Res. Def. Council, Inc. v. Morton","cite":"458 F.2d 827","y":1972,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/458/827/","by":{"3":"25"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Defs. of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"3":"36"}},{"t":"case","label":"Nat’l Helium Corp. v. Morton","cite":"486 F.2d 995","y":1973,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/486/995/","by":{"3":"8"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"586 U.S. 105","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"43"}},{"t":"case","label":"N.Y. Nat. Res. Def. Council, Inc. v. Kleppe","cite":"429 U.S. 1307","y":1976,"url":"https://supreme.justia.com/cases/federal/us/429/1307/","sc":1,"by":{"3":"41"}},{"t":"case","label":"Rocky Mountain Wild v. Dallas","cite":"98 F.4th 1263","y":2024,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/98/1263/","sum":"Noting that the effects of a proposed development that a right-of-way would facilitate were “characteristic” foreseeable effects.","sumSrc":"brief:3","by":{"3":"28"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"3":"42"}},{"t":"case","label":"Sierra Club v. Marsh","cite":"769 F.2d 868","y":1985,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/769/868/","by":{"3":"23, 26, 27","4":"9"}},{"t":"case","label":"Sierra Club v. Sigler","cite":"695 F.2d 957","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/695/957/","sum":"Explaining that if an agency identifies a result of a project “as a ‘selling point,’ ” the environmental effects of that result are reasonably foreseeable.","sumSrc":"brief:3","by":{"3":"27"}},{"t":"case","label":"Staub v. Proctor Hosp.","cite":"562 U.S. 411","y":2011,"id":"2010/09-400","sc":1,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"3":"40"}},{"t":"case","label":"Thacker v. Tenn. Valley Auth.","cite":"587 U.S. 218","y":2019,"url":"https://supreme.justia.com/cases/federal/us/587/218/","sc":1,"by":{"3":"48"}},{"t":"case","label":"Trout Unlimited v. Morton","cite":"509 F.2d 1276","y":1974,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/509/1276/","by":{"3":"26","4":"12"}},{"t":"case","label":"Visa v. Osborn","cite":"580 U.S. 993","y":2016,"id":"2016/15-961","sc":1,"sum":"A case in which the Court would have determined whether allegations that members of a business organization agreed to adhere to the organization’s rules and possessed governance rights to the organization are sufficient to plead that there was a conspiracy under the Sherman Act.","sumSrc":"Oyez","by":{"3":"30"}},{"t":"usc","label":"15 U.S.C. § 793","url":"https://www.law.cornell.edu/uscode/text/15/793","subs":["(d)"],"by":{"3":"42"}},{"t":"usc","label":"16 U.S.C. § 544o","url":"https://www.law.cornell.edu/uscode/text/16/544o","subs":["(f)"],"by":{"3":"42"}},{"t":"usc","label":"16 U.S.C. § 824p","url":"https://www.law.cornell.edu/uscode/text/16/824p","subs":["(h)","(h)(4)(B)"],"by":{"3":"42, 42"}},{"t":"usc","label":"16 U.S.C. § 6514","url":"https://www.law.cornell.edu/uscode/text/16/6514","by":{"3":"42"}},{"t":"usc","label":"23 U.S.C. § 139","url":"https://www.law.cornell.edu/uscode/text/23/139","subs":["(h)"],"by":{"3":"43, 43"}},{"t":"usc","label":"33 U.S.C. § 2348","url":"https://www.law.cornell.edu/uscode/text/33/2348","subs":["(g)(2)(A)","(h)(5)"],"by":{"3":"43, 43"}},{"t":"usc","label":"42 U.S.C. § 4370m-1","url":"https://www.law.cornell.edu/uscode/text/42/4370m-1","by":{"3":"42"}},{"t":"usc","label":"42 U.S.C. § 4370m-4","url":"https://www.law.cornell.edu/uscode/text/42/4370m-4","subs":["(d)(1)"],"by":{"3":"43"}},{"t":"usc","label":"42 U.S.C. § 5175","url":"https://www.law.cornell.edu/uscode/text/42/5175","subs":["(1976)"],"by":{"3":"42"}},{"t":"usc","label":"42 U.S.C. § 10141","url":"https://www.law.cornell.edu/uscode/text/42/10141","subs":["(c)"],"by":{"3":"42"}},{"t":"usc","label":"42 U.S.C. § 10196","url":"https://www.law.cornell.edu/uscode/text/42/10196","subs":["(b)"],"by":{"3":"42"}},{"t":"usc","label":"43 U.S.C. § 1652","url":"https://www.law.cornell.edu/uscode/text/43/1652","subs":["(d)"],"by":{"3":"42"}},{"t":"law","label":"Pub. L. No. 109-58","url":"https://www.govinfo.gov/link/plaw/109/public/58","by":{"3":"42"}},{"t":"law","label":"Fixing America’s Surface Transportation Act, Pub. L. No. 114-94","url":"https://www.govinfo.gov/link/plaw/114/public/94","by":{"3":"42"}},{"t":"law","label":"Pub. L. No. 106-398","url":"https://www.govinfo.gov/link/plaw/106/public/398","by":{"3":"42"}},{"t":"law","label":"Pub. L. No. 108-148","url":"https://www.govinfo.gov/link/plaw/108/public/148","by":{"3":"42"}},{"t":"law","label":"Pub. L. No. 104-88","url":"https://www.govinfo.gov/link/plaw/104/public/88","by":{"3":"12"}},{"t":"law","label":"Infrastructure Investment and Jobs Act, Pub. L. No. 117-58","url":"https://www.govinfo.gov/link/plaw/117/public/58","by":{"3":"43"}},{"t":"usc","label":"42 U.S.C. § 4335","url":"https://www.law.cornell.edu/uscode/text/42/4335","by":{"3":"32"}},{"t":"usc","label":"42 U.S.C. § 4336c","url":"https://www.law.cornell.edu/uscode/text/42/4336c","by":{"3":"10"}},{"t":"usc","label":"42 U.S.C. § 4336d","url":"https://www.law.cornell.edu/uscode/text/42/4336d","by":{"3":"43"}},{"t":"law","label":"Moving Ahead for Progress in the 21st Century Act, Pub. L. No. 112-141","url":"https://www.govinfo.gov/link/plaw/112/public/141","by":{"3":"43"}},{"t":"law","label":"Pub. L. No. 113-121","url":"https://www.govinfo.gov/link/plaw/113/public/121","by":{"3":"43"}},{"t":"reg","label":"40 C.F.R. § 1500.1","url":"https://www.ecfr.gov/current/title-40/section-1500.1","subs":["(b)"],"by":{"3":"9"}},{"t":"reg","label":"40 C.F.R. § 1500.4","url":"https://www.ecfr.gov/current/title-40/section-1500.4","subs":["(p)"],"by":{"3":"8"}},{"t":"reg","label":"40 C.F.R. § 1501.4","url":"https://www.ecfr.gov/current/title-40/section-1501.4","by":{"3":"9"}},{"t":"reg","label":"40 C.F.R. § 1501.6","url":"https://www.ecfr.gov/current/title-40/section-1501.6","by":{"3":"9"}},{"t":"reg","label":"40 C.F.R. § 1502.7","url":"https://www.ecfr.gov/current/title-40/section-1502.7","by":{"3":"9"}},{"t":"reg","label":"40 C.F.R. § 1502.20","url":"https://www.ecfr.gov/current/title-40/section-1502.20","by":{"3":"9"}},{"t":"reg","label":"35 Fed. Reg. 7390","url":"https://www.govinfo.gov/link/fr/35/7390","by":{"3":"5, 26"}},{"t":"reg","label":"36 Fed. Reg. 7724","url":"https://www.govinfo.gov/link/fr/36/7724","by":{"3":"7, 26"}},{"t":"reg","label":"46 Fed. Reg. 18,026","url":"https://www.govinfo.gov/link/fr/46/18026","by":{"3":"26"}},{"t":"reg","label":"51 Fed. Reg. 15,618","url":"https://www.govinfo.gov/link/fr/51/15618","by":{"3":"9"}},{"t":"case","label":"Marin Audubon Soc. v. FAA, --- F.4th ----","cite":"2024 WL 4745044","y":2024,"court":"D.C. Cir. Nov. 12","sum":"Holding that “CEQ regulations, which purport to govern how all federal agencies must comply with [NEPA], are ultra vires”.","sumSrc":"brief:4","by":{"4":"13"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"4":"16"}},{"t":"case","label":"Twitter, Inc. v. Taamneh","cite":"598 U.S. 471","y":2023,"id":"2022/21-1496","sc":1,"sum":"Plaintiffs’ allegations that the social-media-company defendants aided and abetted ISIS in its terrorist attack on a nightclub in Istanbul, Turkey fail to state a claim under 18 U. S. C. §2333(d)(2).","sumSrc":"Holding (supremecourt.gov)","by":{"4":"16"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"4":"22"}},{"t":"case","label":"Pet. for Writ of Cert, Winter v. Natural Resources Defense Council, Inc.","cite":"2008 WL 859374","y":2008,"court":"U.S. Mar. 31","by":{"4":"21"}}]};